const wh = $('Receive Shopify Order Webhook').first();

// Decode the raw body we just verified. Parsed here and ONLY here, so nothing
// upstream can re-serialise the bytes the signature was computed over.
let raw = '';
try {
  const bin = wh.binary && wh.binary.data;
  if (bin && bin.data) raw = Buffer.from(bin.data, 'base64').toString('utf8');
} catch (e) { /* fall through */ }
if (!raw && wh.json && wh.json.body) {
  raw = typeof wh.json.body === 'string' ? wh.json.body : JSON.stringify(wh.json.body);
}

let p = {};
let parse_error = null;
try { p = JSON.parse(raw); } catch (e) { parse_error = String(e.message || e); }

function clean(v) {
  if (v == null) return null;
  const s = String(v).trim();
  return s.length ? s : null;
}

// shop_money is what the MERCHANT books; presentment_money is what the customer
// saw. carts.currency holds presentment, carts.recovered_currency holds shop -
// they are genuinely different numbers and conflating them misreports revenue.
const tps = p.total_price_set || {};
const shop = tps.shop_money || {};
const pres = tps.presentment_money || {};

const checkoutToken = clean(p.checkout_token);

return [{ json: {
  parse_error: parse_error,
  checkout_token: checkoutToken,
  has_checkout_token: !!checkoutToken,
  // Prefer the GraphQL gid so this matches what workflow 02 writes for the same order.
  order_id: clean(p.admin_graphql_api_id) || (p.id != null ? String(p.id) : null),
  order_ref: clean(p.name),
  order_created_at: clean(p.created_at),
  financial_status: clean(p.financial_status),
  shop_amount: (shop.amount !== undefined && shop.amount !== null) ? Number(shop.amount) : (p.total_price != null ? Number(p.total_price) : null),
  shop_currency: clean(shop.currency_code) || clean(p.currency),
  presentment_amount: (pres.amount !== undefined && pres.amount !== null) ? Number(pres.amount) : null,
  presentment_currency: clean(pres.currency_code) || clean(p.presentment_currency),
  customer_phone: clean(p.phone) || clean((p.customer || {}).phone) || null,
  shop_domain: wh.json && wh.json.headers ? (wh.json.headers['x-shopify-shop-domain'] || null) : null
} }];

const order = $('Parse Order Payload').first().json;
const resp = $input.first().json;
const httpCode = (resp && resp.statusCode) ? resp.statusCode : 0;
const body = resp ? resp.body : null;

const lookupOk = (httpCode === 200 && Array.isArray(body));
const cart = (lookupOk && body.length > 0) ? body[0] : null;

// Statuses this workflow is allowed to close. Anything else is either already
// closed (nothing to do) or opted out (must not be overwritten).
const OPEN = ['pending_verification', 'abandoned', 'recovering', 'exhausted'];
const CLOSED = ['recovered', 'converted_before_first_touch'];

let outcome = 'no_match';
let closeStatus = null;

if (!lookupOk) {
  outcome = 'lookup_failed';
} else if (cart) {
  if (cart.opted_out === true || cart.status === 'opted_out') {
    // They asked us to stop and bought anyway. That is a sale, not a recovery,
    // and overwriting the status here would also destroy the suppression flag.
    outcome = 'converted_after_opt_out';
  } else if (CLOSED.indexOf(cart.status) >= 0) {
    // The 15-minute sweep already attributed this one, or Shopify retried the
    // webhook. Either way there is nothing left to write.
    outcome = 'already_closed';
  } else if (OPEN.indexOf(cart.status) >= 0) {
    outcome = 'attribute';
    // Locked decision #9: a cart that converted before we ever messaged it is
    // NOT a recovery and must never be counted as one.
    closeStatus = (cart.touches_sent || 0) > 0 ? 'recovered' : 'converted_before_first_touch';
  } else {
    outcome = 'unexpected_status';
  }
}

return [{ json: {
  outcome: outcome,
  close_status: closeStatus,
  lookup_ok: lookupOk,
  lookup_status_code: httpCode,
  cart_id: cart ? cart.id : null,
  cart_status: cart ? cart.status : null,
  touches_sent: cart ? cart.touches_sent : null,
  customer_first_name: cart ? cart.customer_first_name : null,
  customer_last_name: cart ? cart.customer_last_name : null,
  cart_currency: cart ? cart.currency : null,
  cart_total: cart ? cart.cart_total : null,
  checkout_token: order.checkout_token,
  order_id: order.order_id,
  order_ref: order.order_ref,
  shop_amount: order.shop_amount,
  shop_currency: order.shop_currency,
  presentment_amount: order.presentment_amount,
  presentment_currency: order.presentment_currency
} }];
